mapper.select:
SELECT n.id, n.title, n.content, n.publisher_id, n.publisher_name, n.publisher_role, u.college as publisher_college, n.is_top, n.status, n.create_time, n.update_time, CASE WHEN nr.id IS NULL THEN 0 ELSE 1 END as is_read FROM notice n LEFT JOIN user u ON n.publisher_id = u.id LEFT JOIN notice_read nr ON nr.notice_id = n.id AND nr.user_id = #{userId}
AND n.title LIKE CONCAT('%', #{title}, '%')
AND n.status = 'normal'
AND ( n.publisher_role = '系统管理员'
AND 1 = 1
OR u.college = #{viewerCollege}
)
AND nr.id IS NULL
AND nr.id IS NOT NULL
ORDER BY n.is_top DESC, n.create_time DESC
